document.addEventListener('DOMContentLoaded',function(){const t=document.querySelector('.menu-toggle'),n=document.querySelector('#site-nav');if(t&&n){t.addEventListener('click',function(){const o=t.getAttribute('aria-expanded')==='true';t.setAttribute('aria-expanded',String(!o));n.classList.toggle('is-open',!o)});n.querySelectorAll('a').forEach(function(e){e.addEventListener('click',function(){t.setAttribute('aria-expanded','false');n.classList.remove('is-open')})})}const s=[...document.querySelectorAll('.news-slide')],d=[...document.querySelectorAll('.news-dot')],p=document.querySelector('.news-prev'),a=document.querySelector('.news-next');if(!s.length)return;let i=0;let r;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;function show(e){i=(e+s.length)%s.length;s.forEach((t,n)=>t.classList.toggle('is-active',n===i));d.forEach((t,n)=>{t.classList.toggle('is-active',n===i);t.setAttribute('aria-selected',String(n===i))})}function next(){show(i+1)}d.forEach((t,n)=>t.addEventListener('click',()=>show(n)));p&&p.addEventListener('click',()=>show(i-1));a&&a.addEventListener('click',next);function start(){window.clearInterval(r);if(!reduced&&!document.hidden)r=window.setInterval(next,7000)}const f=document.querySelector('.news-feature');f&&f.addEventListener('mouseenter',()=>window.clearInterval(r));f&&f.addEventListener('mouseleave',start);document.addEventListener('visibilitychange',start);start();});
